    fjusch: { t: 'Jugendgefährdender Ort – § 8 JuSchG', merk: ['Kind oder Jugendliche/r an einem Ort mit unmittelbarer Gefahr für das körperliche, geistige oder seelische Wohl', 'Erforderliche Maßnahme: zum Verlassen anhalten, der erziehungsberechtigten Person zuführen oder – wenn niemand erreichbar ist – in die Obhut des Jugendamtes bringen'], hin: ['Die Zuführung ist meist nur Freiheitsbeschränkung; längeres Festhalten braucht eine eigene Grundlage (§ 35 Abs. 1 Nr. 1 oder Abs. 2 PolG NRW, § 42 SGB VIII) und die Verfahrensregeln', 'In schwierigen Fällen Jugendamt über den Ort unterrichten'], law: ['juschg8', 'sgb8_42'] },
    fsgb42: { t: 'Inobhutnahme durch das Jugendamt – § 42 SGB VIII', merk: ['Kind bittet um Obhut, dringende Gefahr für das Kindeswohl oder unbegleitete Einreise', 'Freiheitsentziehende Maßnahmen nur zur Abwendung einer Gefahr für Leib oder Leben des Kindes oder Dritter (Abs. 5)', 'Ohne gerichtliche Entscheidung spätestens mit Ablauf des Folgetages beenden'], hin: ['Die Polizei wird hinzugezogen, wenn unmittelbarer Zwang nötig ist (Abs. 6)'], law: ['sgb8_42'] },
    fauf: { t: 'Festhalten zur Sicherungshaft – § 62 Abs. 5 AufenthG', merk: ['Dringender Verdacht, dass die Voraussetzungen der Sicherungshaft vorliegen (§ 62 Abs. 3 S. 1)', 'Richterliche Entscheidung kann nicht vorher eingeholt werden', 'Begründeter Verdacht, dass sich die Person der Anordnung der Sicherungshaft entziehen will'], hin: ['Befugt ist die für den Haftantrag zuständige Behörde; nach § 71 Abs. 5 AufenthG sind auch die Polizeien der Länder für Festnahme und Haftantrag zuständig', 'Unverzüglich dem Richter vorführen; Verfahren nach Buch 7 FamFG'], law: ['aufenthg62', 'famfg415', 'famfg428'] },
    fifsg: { t: 'Zwangsweise Absonderung – § 30 Abs. 2 IfSG', merk: ['Absonderung durch die zuständige Behörde angeordnet', 'Die Person befolgt die Anordnung nicht oder wird sie voraussichtlich nicht befolgen', 'Zwangsweise Absonderung in einem abgeschlossenen Krankenhaus bzw. einer abgeschlossenen Einrichtung'], hin: ['Gerichtliche Entscheidung nach Buch 7 FamFG; ordnet die Behörde im Eilfall selbst an, ist sie unverzüglich nachzuholen, sonst Freilassung mit Ablauf des Folgetages (§ 428 FamFG); die Polizei leistet Vollzugshilfe'], law: ['ifsg30', 'famfg415', 'famfg428'] },
    v_uhaft: { t: 'Vollzug eines Haftbefehls – §§ 114 ff. StPO', merk: ['Gültiger Haftbefehl, Person identisch (Fahndungsabgleich)'], hin: ['Haftbefehl bzw. Abschrift aushändigen (§ 114a), schriftlich belehren (§ 114b), Benachrichtigung ermöglichen (§ 114c)', 'Unverzüglich, spätestens am Tag nach der Ergreifung dem zuständigen Gericht vorführen; sonst nächstes Amtsgericht (§§ 115, 115a)'], law: ['p115', 'p114b', 'p114c'] },
    v_vollstr: { t: 'Vollstreckungshaftbefehl – § 457 Abs. 2 StPO', merk: ['Haftbefehl der Vollstreckungsbehörde (Staatsanwaltschaft) zur Vollstreckung einer Freiheitsstrafe', 'Person identisch'], hin: ['Einlieferung in die Justizvollzugsanstalt', 'Bei Ersatzfreiheitsstrafe kann die Vollstreckung durch Zahlung des im Haftbefehl genannten Betrags abgewendet werden'], law: ['p457'] },
    v_hv: { t: 'Haftbefehl oder Vorführung zur Hauptverhandlung – § 230 Abs. 2 StPO', merk: ['Angeklagter ist der Hauptverhandlung unentschuldigt ferngeblieben', 'Gericht hat Vorführung angeordnet oder Haftbefehl erlassen'], hin: ['Vorführung: Person zum Termin bringen; Haftbefehl: Vollzug wie § 114 ff.'], law: ['p230'] },
