  /* Begriffe im Fließtext erkennen (längste zuerst, ganze Wörter, ohne Lookbehind für ältere iOS) */
  const WCH = 'A-Za-zÄÖÜäöüß';
  const TERMS = [];
  for (const [k, e] of Object.entries(LEX)) (e.terms || []).forEach(t => { const re = t.startsWith('re:') ? t.slice(3) : t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); TERMS.push({ k, re, rx: new RegExp('^(?:' + re + ')$', 'i'), len: t.length }); });
  TERMS.sort((a, b) => b.len - a.len);
  const TRE = TERMS.length ? new RegExp('(^|[^' + WCH + '])(' + TERMS.map(t => t.re).join('|') + ')(?![' + WCH + '])', 'gi') : null;
  function termify(text, self, used) {
    const s = String(text ?? ''); if (!TRE) return esc(s);
    let out = '', last = 0, m; used = used || new Set(); TRE.lastIndex = 0;
    while ((m = TRE.exec(s))) {
      const word = m[2], start = m.index + m[1].length;
      const t = TERMS.find(x => x.rx.test(word));
      if (!t || t.k === self || used.has(t.k)) { if (TRE.lastIndex === m.index) TRE.lastIndex++; continue; }
      used.add(t.k);
      out += esc(s.slice(last, start)) + `<button type="button" class="fe-term" data-fe-m="${t.k}">${esc(word)}</button>`;
      last = start + word.length;
    }
    return out + esc(s.slice(last));
  }
